    int b = powerModulus(c, 1 << (m - i - 1), p);
    c = multiplyModulus(b, b, p);
    t = multiplyModulus(t, c, p);
    m = i;
    result = multiplyModulus(result, b, p);
  }

  return Solution(result, p - result, true);
}

